SELECT cs.cs_sold_date_sk, w.w_warehouse_name, cs.cs_quantity * cs.cs_wholesale_cost AS wholesale_amount, cs.cs_quantity * cs.cs_sales_price AS sales_amount, cs.cs_ext_discount_amt + cs.cs_ext_tax AS discount_plus_tax, CASE WHEN cs.cs_quantity > 88 THEN 'Large' ELSE 'Small' END AS quantity_category, CASE w.w_state WHEN 'CA' THEN 'West' WHEN 'NY' THEN 'East' ELSE 'Other' END AS region_category FROM catalog_sales cs JOIN warehouse w ON cs.cs_warehouse_sk = w.w_warehouse_sk WHERE cs.cs_sold_date_sk = 2450837
